def random_selection(var_list, num):
    if num > len(var_list):
        print("Number of variables requested is more than available variables.")
        return
    else:
        # Store the result in a new list to avoid repetition
        result = [] 
        for i in range(num):
            var = random.choice(var_list)
            # To ensure no repetition of variables
            while var in result:
                var = random.choice(var_list)
            result.append(var)
        return result

