def convert_temp(value, from_unit='C', to_unit='F', round_to=2):
    if from_unit.upper() == 'C' and to_unit.upper() == 'F':
        return round((value * 9/5) + 32, round_to)
    elif from_unit.upper() == 'F' and to_unit.upper() == 'C':
        return round((value - 32) * 5/9, round_to)
    else:
        return "Invalid input"

