def get_antidepressant_medication_priority(patient):
    """
    Compute the antidepressant medication priority of the patient.
    patient: A patient object with attributes: age, resource_availability, comorbidities, severity, insurance_status, symptoms, duration_of_condition
    """
    score = 0

    # Higher severity leads to higher priority
    if 'chronic depression' in patient.symptoms:
        score += 3
    elif 'mild depression' in patient.symptoms:
        score += 2
    else:
        score += 1

    # More comorbidities increase priority
    if patient.comorbidities >= 3:
        score += 3
    elif patient.comorbidities >= 1:
        score += 2

    # Older patients with higher severity may require priority
    if patient.age >= 65 and 'chronic depression' in patient.symptoms:
        score += 2

    # Uninsured patients may not have access to medication
    if patient.insurance_status == 'uninsured':
        score -= 3  # This directly reduces the priority due to lack of insurance

    # Limited resource availability might reduce priority
    if not patient.resource_availability:
        score -= 2

    # Ensure score remains within a valid range (1-5)
    score = max(1, min(score, 5))

    return score

