import requests

def scrape_data(url):
    response = requests.get(url)  # Send a HTTP request to the specified URL
    soup = BeautifulSoup(response.text, 'html.parser')  # Parse the HTTP response
    data = {}

    # Example: Scraping data from a table
    table = soup.find('table', {'class': 'example-table'})  # Find the table by its class
    rows = table.find_all('tr')  # Find all rows in the table

    for row in rows:
        columns = row.find_all(['td', 'th'])  # Find all columns (table data) and table headers in the row
        for i, column in enumerate(columns):
            # Assume that the first column is a header and the rest are data
            if i == 0:
                header = column.text  # Get the text from the column
                data[header] = []
            else:
                data[header].append(column.text)  # Get the text from the column and add to the data list

    return data

