def fibonacci(n):
    if n <= 0:
        return "Input should be a positive integer."
    elif n == 1:
        return 0
    elif n == 2:
        return 1
    else:
        nth_fibo = 0
        second_last_fibo = 0
        last_fibo = 1
        for i in range(3, n+1):
            nth_fibo = last_fibo + second_last_fibo
            second_last_fibo = last_fibo
            last_fibo = nth_fibo
        return nth_fibo

