def isHappy(n):
    slow = n
    fast = getNext(n)
    while fast != 1 and slow != fast:
        slow = getNext(slow)
        fast = getNext(getNext(fast))
    return fast == 1

def getNext(n):
    totalSum = 0
    while n > 0:
        n, digit = divmod(n, 10)
        totalSum += digit ** 2
    return totalSum

